import { Expression, FeederBuilder, Session, underlyingSessionTo, wrapFeederBuilder } from "@gatling.io/core";

import { JdbcProtocolBuilder, wrapJdbcProtocolBuilder } from "./protocol";
import { Jdbc, wrapJdbc } from "./request";

export * from "./checks";
export * from "./params";
export * from "./protocol";
export * from "./request";

import { JdbcDsl as JvmJdbcDsl } from "@gatling.io/jvm-types";

import JvmJdbcProtocolBuilderBase = io.gatling.javaapi.jdbc.JdbcProtocolBuilder$Base;

// static fields aren't generated by java2ts
const jvmJdbcProtocolBuilderBase: JvmJdbcProtocolBuilderBase = (JvmJdbcDsl as any).jdbc;

export interface JdbcApply {
  /**
   * Bootstrap a JDBC request
   *
   * @param requestName - the name of the request, expressed as a Gatling Expression Language String
   * @returns the next DSL step
   */
  (requestName: string): Jdbc;

  /**
   * Bootstrap a JDBC request
   *
   * @param requestName - the name of the request, expressed as a function
   * @returns the next DSL step
   */
  (requestName: (session: Session) => string): Jdbc;
}

export interface JdbcProtocolBuilderBase {
  /**
   * Open connections to the database with the given JDBC URL. The JDBC driver of the database must
   * be declared in the "gatling.jvmDependencies" section of package.json.
   *
   * @param url - the JDBC URL
   * @returns a new JdbcProtocolBuilder instance
   */
  url(url: string): JdbcProtocolBuilder;

  /**
   * Get connections from a javax.sql.DataSource, configured with driver specific settings. Gatling
   * still pools the connections itself, so pass a plain DataSource, not a pooling one.
   *
   * @param dataSource - the javax.sql.DataSource
   * @returns a new JdbcProtocolBuilder instance
   */
  dataSource(dataSource: unknown): JdbcProtocolBuilder;
}

const jdbcApply = (requestName: Expression<string>): Jdbc =>
  wrapJdbc(
    typeof requestName === "function" ? JvmJdbcDsl.jdbc(underlyingSessionTo(requestName)) : JvmJdbcDsl.jdbc(requestName)
  );

const jdbcProtocolBuilderBase: JdbcProtocolBuilderBase = {
  url: (url: string) => wrapJdbcProtocolBuilder(jvmJdbcProtocolBuilderBase.url(url)),
  dataSource: (dataSource: unknown) => wrapJdbcProtocolBuilder(jvmJdbcProtocolBuilderBase.dataSource(dataSource))
};

/**
 * The entrypoint of the JDBC DSL: jdbc.url(...) bootstraps a protocol, jdbc("name") a request
 */
export const jdbc: JdbcApply & JdbcProtocolBuilderBase = Object.assign(jdbcApply, jdbcProtocolBuilderBase);

/**
 * Bootstrap a feeder that loads its records from a database with a SQL query, when the simulation
 * starts. The JDBC driver of the database must be declared in the "gatling.jvmDependencies" section
 * of package.json.
 *
 * @param url - the JDBC URL of the database
 * @param username - the username
 * @param password - the password
 * @param sql - the SQL query
 * @returns a FeederBuilder
 */
export const jdbcFeeder = (url: string, username: string, password: string, sql: string): FeederBuilder<unknown> =>
  wrapFeederBuilder(JvmJdbcDsl.jdbcFeeder(url, username, password, sql) as any);
